<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#1b263b">
<title>Still Water — the calmest game</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #0d1b2a; }
  body { font-family: "Cormorant Garamond", "EB Garamond", Georgia, serif; color: #e8e4dc; -webkit-font-smoothing: antialiased; }
  canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
  .veil { position: fixed; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; background: radial-gradient(ellipse at center, rgba(13,27,42,0.55), rgba(13,27,42,0.92)); backdrop-filter: blur(2px); z-index: 10; transition: opacity 1.6s ease, visibility 1.6s ease; cursor: pointer; }
  .veil.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
  .title { font-size: clamp(2.2rem, 6vw, 4rem); font-weight: 300; letter-spacing: 0.18em; text-transform: uppercase; color: #e8e4dc; text-shadow: 0 0 40px rgba(168,216,234,0.35); }
  .subtitle { font-size: clamp(0.95rem, 2vw, 1.2rem); font-weight: 300; letter-spacing: 0.24em; color: #b8c9e8; opacity: 0.85; }
  .hint { margin-top: 24px; font-size: 0.9rem; letter-spacing: 0.18em; color: #9aa7c4; opacity: 0.7; animation: breathe 3.6s ease-in-out infinite; }
  @keyframes breathe { 0%,100%{opacity:0.45} 50%{opacity:0.85} }
  .corner { position: fixed; z-index: 5; display: flex; gap: 10px; padding: 14px; }
  .corner.tr { top: 0; right: 0; }
  .corner.bl { bottom: 0; left: 0; }
  button.icon { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); color: #e8e4dc; width: 40px; height: 40px; border-radius: 50%; cursor: pointer; font-family: inherit; font-size: 1rem; display: grid; place-items: center; transition: background 0.3s ease, transform 0.3s ease; backdrop-filter: blur(6px); }
  button.icon:hover { background: rgba(255,255,255,0.14); transform: scale(1.06); }
  .wishbar { position: fixed; bottom: 18px; right: 18px; z-index: 5; display: flex; align-items: center; gap: 8px; font-size: 0.8rem; letter-spacing: 0.16em; color: #b8c9e8; opacity: 0.75; }
  .wishdots { display: flex; gap: 6px; }
  .wishdots span { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,0.18); transition: background 0.6s ease, box-shadow 0.6s ease; }
  .wishdots span.lit { background: #ffd6a5; box-shadow: 0 0 10px #ffd6a5; }
  .msg { position: fixed; top: 50%; left: 50%; transform: translate(-50%,-50%); z-index: 6; font-size: clamp(1.2rem,3vw,1.8rem); letter-spacing: 0.24em; color: #ffd6a5; text-shadow: 0 0 30px rgba(255,214,165,0.5); pointer-events: none; opacity: 0; transition: opacity 1.2s ease; }
  .msg.show { opacity: 1; }
  @media (max-width: 600px) { .corner { padding: 10px; } button.icon { width: 36px; height: 36px; } }
</style>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@300;400&display=swap" rel="stylesheet">
</head>
<body>
<canvas id="c"></canvas>

<div class="veil" id="veil">
  <div class="title">Still Water</div>
  <div class="subtitle">a game with nothing to win</div>
  <div class="hint">tap to enter · move slowly</div>
</div>

<div class="corner tr">
  <button class="icon" id="muteBtn" aria-label="mute">♪</button>
  <button class="icon" id="resetBtn" aria-label="reset garden">↺</button>
</div>

<div class="wishbar">
  <div class="wishdots" id="wishdots"></div>
</div>

<div class="msg" id="msg"></div>

<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  let W = 0, H = 0, dpr = 1;
  const state = {
    started: false,
    muted: false,
    time: 0,
    pointer: { x: 0, y: 0, tx: 0, ty: 0, active: false, down: false },
    orb: { x: 0, y: 0, trail: [] },
    ripples: [],
    fish: [],
    flowers: [],
    fireflies: [],
    wishes: 0,
    msgTimer: 0,
    lastRipple: 0,
    lastChime: 0,
    autoAngle: 0,
  };

  // ---------- helpers ----------
  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = W * dpr; canvas.height = H * dpr;
    canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (!state.started) {
      state.orb.x = state.pointer.x = state.pointer.tx = W * 0.5;
      state.orb.y = state.pointer.y = state.pointer.ty = H * 0.62;
    }
  }
  window.addEventListener('resize', resize);

  function hexToRgb(h) {
    const v = h.replace('#',''); const n = parseInt(v,16);
    return [(n>>16)&255, (n>>8)&255, n&255];
  }
  function lerp(a,b,t){ return a + (b-a)*t; }
  function lerpColor(c1,c2,t){
    const a=hexToRgb(c1), b=hexToRgb(c2);
    return `rgb(${Math.round(lerp(a[0],b[0],t))},${Math.round(lerp(a[1],b[1],t))},${Math.round(lerp(a[2],b[2],t))})`;
  }
  function clamp(v,a,b){ return Math.max(a, Math.min(b, v)); }

  // sky keyframes
  const skyKeys = [
    { t: 0.00, top: '#a8d8ea', bot: '#e8f4f8' },
    { t: 0.25, top: '#ffb4a2', bot: '#c9a0dc' },
    { t: 0.50, top: '#0d1b2a', bot: '#1b263b' },
    { t: 0.75, top: '#ffd6a5', bot: '#b8c9e8' },
    { t: 1.00, top: '#a8d8ea', bot: '#e8f4f8' },
  ];
  function skyAt(phase) {
    // find segment
    let i = 0;
    for (; i < skyKeys.length-1; i++) if (phase >= skyKeys[i].t && phase < skyKeys[i+1].t) break;
    const a = skyKeys[i], b = skyKeys[i+1];
    const seg = (phase - a.t) / (b.t - a.t);
    const t = clamp(seg, 0, 1);
    return { top: lerpColor(a.top, b.top, t), bot: lerpColor(a.bot, b.bot, t) };
  }

  // ---------- init entities ----------
  function initEntities() {
    state.fish = [];
    const colors = ['#f4a261','#e9c46a','#ffffff','#e76f51','#2a9d8f','#f6bd60'];
    for (let i = 0; i < 7; i++) {
      state.fish.push({
        x: Math.random()*W, y: H*0.55 + Math.random()*H*0.4,
        angle: Math.random()*Math.PI*2,
        speed: 0.25 + Math.random()*0.45,
        size: 0.8 + Math.random()*0.6,
        color: colors[i % colors.length],
        phase: Math.random()*10,
        turnTimer: 0,
      });
    }
    state.flowers = [];
    for (let i = 0; i < 5; i++) {
      state.flowers.push({
        x: W*0.15 + Math.random()*W*0.7,
        y: H*0.6 + Math.random()*H*0.3,
        bloom: 1, phase: Math.random()*10, sway: Math.random()*Math.PI*2,
      });
    }
    state.fireflies = [];
    for (let i = 0; i < 18; i++) {
      state.fireflies.push({
        x: Math.random()*W, y: Math.random()*H*0.7,
        vx: (Math.random()-0.5)*0.4, vy: (Math.random()-0.5)*0.4,
        phase: Math.random()*Math.PI*2,
        size: 1.5 + Math.random()*1.5,
        alive: true,
      });
    }
    state.ripples = [];
    state.orb.trail = [];
    state.wishes = 0;
    updateWishDots();
  }

  function updateWishDots() {
    const el = document.getElementById('wishdots');
    el.innerHTML = '';
    for (let i = 0; i < 7; i++) {
      const s = document.createElement('span');
      if (i < state.wishes) s.classList.add('lit');
      el.appendChild(s);
    }
  }

  function showMessage(text) {
    const m = document.getElementById('msg');
    m.textContent = text;
    m.classList.add('show');
    clearTimeout(state._msgT);
    state._msgT = setTimeout(() => m.classList.remove('show'), 3200);
  }

  // ---------- audio ----------
  let audioCtx = null, masterGain = null, convolver = null;
  let padFilter = null;
  const pentatonic = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25];
  function initAudio() {
    if (audioCtx) return;
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = state.muted ? 0 : 0.28;

    // convolver reverb
    convolver = audioCtx.createConvolver();
    const len = Math.floor(audioCtx.sampleRate * 2.2);
    const buf = audioCtx.createBuffer(2, len, audioCtx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch);
      for (let i = 0; i < len; i++) d[i] = (Math.random()*2 - 1) * Math.pow(1 - i/len, 3.2);
    }
    convolver.buffer = buf;
    const dry = audioCtx.createGain(); dry.gain.value = 0.62;
    const wet = audioCtx.createGain(); wet.gain.value = 0.38;
    masterGain.connect(dry); dry.connect(audioCtx.destination);
    masterGain.connect(convolver); convolver.connect(wet); wet.connect(audioCtx.destination);

    // ambient pad
    padFilter = audioCtx.createBiquadFilter();
    padFilter.type = 'lowpass'; padFilter.frequency.value = 720; padFilter.Q.value = 0.7;
    padFilter.connect(masterGain);
    const padNotes = [130.81, 196.00, 261.63, 329.63];
    padNotes.forEach((f, i) => {
      const osc = audioCtx.createOscillator();
      osc.type = 'sine'; osc.frequency.value = f;
      const g = audioCtx.createGain(); g.gain.value = 0.06;
      const lfo = audioCtx.createOscillator(); lfo.frequency.value = 0.04 + i*0.017;
      const lg = audioCtx.createGain(); lg.gain.value = 0.035;
      lfo.connect(lg); lg.connect(g.gain);
      osc.connect(g); g.connect(padFilter);
      osc.start(); lfo.start();
    });

    // slow chime scheduler
    scheduleChime();
  }
  function scheduleChime() {
    if (!audioCtx) return;
    const delay = 3500 + Math.random()*4500;
    setTimeout(() => {
      if (audioCtx && !state.muted) {
        const f = pentatonic[Math.floor(Math.random()*pentatonic.length)];
        chime(f, 0.12);
      }
      scheduleChime();
    }, delay);
  }
  function chime(freq, vol = 0.16) {
    if (!audioCtx || state.muted) return;
    const osc = audioCtx.createOscillator();
    osc.type = 'sine'; osc.frequency.value = freq;
    const g = audioCtx.createGain();
