  function setMuted(m) {
    state.muted = m;
    if (masterGain) masterGain.gain.setTargetAtTime(m ? 0 : 0.28, audioCtx.currentTime, 0.2);
    document.getElementById('muteBtn').textContent = m ? ' ' : '♪';
  }

  // ---------- input ----------
  function toLocal(e) {
