  canvas.addEventListener('pointermove', (e) => {
    const p = toLocal(e);
    state.pointer.tx = p.x; state.pointer.ty = p.y; state.pointer.active = true;
  });
  canvas.addEventListener('pointerup', (e) => { state.pointer.down = false; });
  canvas.addEventListener('pointerleave', () => { state.pointer.active = false; });

  // also veil click
  document.getElementById('veil').addEventListener('click', () => startGame());
  document.getElementById('muteBtn').addEventListener('click', (e) => { e.stopPropagation(); setMuted(!state.muted); });
  document.getElementById('resetBtn').addEventListener('click', (e) => { e.stopPropagation(); initEntities(); showMessage('garden renewed'); });

  function startGame() {
    if (state.started) return;
    state.started = true;
    document.getElementById('veil').classList.add('hidden');
    initAudio();
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
    initEntities();
    // seed orb position
    state.orb.x = state.pointer.tx = (state.pointer.tx || W*0.5);
    state.orb.y = state.pointer.ty = (state.pointer.ty || H*0.62);
    showMessage('breathe');
  }

  function spawnFlower(x, y) {
    if (!state.started) return;
    // limit
    if (state.flowers.length > 22) state.flowers.shift();
    state.flowers.push({ x, y, bloom: 0, phase: Math.random()*10, sway: Math.random()*Math.PI*2 });
    chime(pentatonic[Math.floor(Math.random()*pentatonic.length)], 0.13);
    state.ripples.push({ x, y, r: 0, alpha: 0.5 });
  }

  function spawnRipple(x, y) {
    state.ripples.push({ x, y, r: 0, alpha: 0.35 });
  }

  // ---------- update ----------
  function update(dt) {
    state.time += dt;
    const t = state.time;

    // pointer target: if inactive, auto drift
    if (!state.pointer.active) {
      state.autoAngle += dt * 0.18;
      state.pointer.tx = W*0.5 + Math.cos(state.autoAngle)*W*0.18;
      state.pointer.ty = H*0.62 + Math.sin(state.autoAngle*0.7)*H*0.12;
    }
    // lerp pointer (dreamy)
    state.pointer.x += (state.pointer.tx - state.pointer.x) * 0.06;
    state.pointer.y += (state.pointer.ty - state.pointer.y) * 0.06;

    // orb follows pointer with extra lag
