    }

    // fish
    for (const f of state.fish) {
      f.phase += dt;
      f.turnTimer -= dt;
      if (f.turnTimer <= 0) {
        f.turnTimer = 1.5 + Math.random()*3;
        f.angle += (Math.random()-0.5)*0.9;
