      ctx.save();
      ctx.globalAlpha = a;
      ctx.fillStyle = '#ffd6a5';
      ctx.beginPath(); ctx.arc(p.x, p.y, Math.max(1, rad), 0, Math.PI*2); ctx.fill();
      ctx.restore();
    }
    // orb
    const orbGlow = ctx.createRadialGradient(state.orb.x, state.orb.y, 0, state.orb.x, state.orb.y, 40);
    orbGlow.addColorStop(0, 'rgba(255,214,165,0.9)');
    orbGlow.addColorStop(0.4, 'rgba(255,214,165,0.35)');
    orbGlow.addColorStop(1, 'rgba(255,214,165,0)');
    ctx.fillStyle = orbGlow;
    ctx.beginPath(); ctx.arc(state.orb.x, state.orb.y, 40, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#fff6e8';
    ctx.beginPath(); ctx.arc(state.orb.x, state.orb.y, 4, 0, Math.PI*2); ctx.fill();

    // fireflies
    for (const ff of state.fireflies) {
      if (!ff.alive) continue;
      const glow = (Math.sin(ff.phase)+1)/2;
      const alpha = 0.4 + glow*0.6;
      const rad = ff.size * (0.9 + glow*0.4);
      const g2 = ctx.createRadialGradient(ff.x, ff.y, 0, ff.x, ff.y, rad*4);
      g2.addColorStop(0, `rgba(255,240,180,${alpha})`);
      g2.addColorStop(0.5, `rgba(255,214,165,${alpha*0.4})`);
      g2.addColorStop(1, 'rgba(255,214,165,0)');
      ctx.fillStyle = g2;
      ctx.beginPath(); ctx.arc(ff.x, ff.y, rad*4, 0, Math.PI*2); ctx.fill();
    }

    // vignette
    const vig = ctx.createRadialGradient(W/2, H/2, Math.min(W,H)*0.35, W/2, H/2, Math.max(W,H)*0.75);
    vig.addColorStop(0, 'rgba(0,0,0,0)');
    vig.addColorStop(1, 'rgba(0,0,0,0.45)');
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, W, H);
  }

  // ---------- loop ----------
  let last = performance.now();
  function loop(now) {
    const dt = Math.min(0.05, (now - last)/1000);
    last = now;
    if (state.started) update(dt);
    else {
      // gentle drift of orb even before start
      state.time += dt;
      state.autoAngle += dt*0.12;
      state.orb.x = W*0.5 + Math.cos(state.autoAngle)*W*0.12;
      state.orb.y = H*0.62 + Math.sin(state.autoAngle*0.7)*H*0.08;
    }
    render();
    requestAnimationFrame(loop);
  }

  // init
  resize();
  initEntities();
  requestAnimationFrame(loop);

  // handle visibility
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) return;
    last = performance.now();
  });
})();
</script>
